def solve(params):
    values=params["values"]
    n=len(values)
    if n==0:
        return 0
    left=0
    cur_sum=0
    seen={}
    best_ending=[0]*n
    for right in range(n):
        v=values[right]
        if v in seen and seen[v]>=left:
            prev=seen[v]
            for k in range(left, prev+1):
                cur_sum-=values[k]
            left=prev+1
        cur_sum+=v
        seen[v]=right
        best_ending[right]=cur_sum
    pref=[0]*n
    cur_best=best_ending[0]
    pref[0]=cur_best
    for i in range(1,n):
        if best_ending[i]>cur_best:
            cur_best=best_ending[i]
        if cur_best>pref[i-1]:
            pref[i]=cur_best
        else:
            pref[i]=pref[i-1]
    # suffix
    right=n-1
    cur_sum=0
    seen={}
    best_starting=[0]*n
    for l in range(n-1,-1,-1):
        v=values[l]
        if v in seen and seen[v]<=right:
            nxt=seen[v]
            for k in range(nxt-1, right):
                pass
            # remove from right side down to nxt
            for k in range(right, nxt-1, -1):
                cur_sum-=values[k]
            right=nxt-1
            # actually need to shrink correctly: window is [l+1 .. right] before adding
            # So we already removed tail beyond new right, now add v
        cur_sum+=v
        seen[v]=l
        # due to positive values, maximal distinct starting at l is window [l .. right]
        best_starting[l]=cur_sum
        # adjust right pointer for next iteration: keep window for next l-1, but right stays as is (max distinct)
        # Need to handle duplicate of next value: loop above handles
        # However cur_sum currently is sum[l..right], correct
    suff=[0]*n
    cur_best=best_starting[n-1]
    suff[n-1]=cur_best
    for i in range(n-2,-1,-1):
        if best_starting[i]>cur_best:
            cur_best=best_starting[i]
        suff[i]=cur_best if cur_best>suff[i+1] else suff[i+1]
        # actually need max of cur_best and suff[i+1]
        if suff[i+1]>cur_best:
            suff[i]=suff[i+1]
        else:
            suff[i]=cur_best
    ans=pref[n-1]
    for i in range(n-1):
        tot=pref[i]+suff[i+1]
        if tot>ans:
            ans=tot
    return int(ans)

