def solve(params):
    values=params["values"]
    n=len(values)
    subs=[]
    for l in range(n):
        seen=set()
        s=0
        for r in range(l,n):
            if values[r] in seen:
                break
            seen.add(values[r])
            s+=values[r]
            subs.append((l,r,s))
    if not subs:
        return 0
    best=max(s for _,_,s in subs)
    m=len(subs)
    for i in range(m):
        l1,r1,s1=subs[i]
        if s1<=best:
            pass
        for j in range(i+1,m):
            l2,r2,s2=subs[j]
            if r1 < l2 or r2 < l1:
                tot=s1+s2
                if tot>best:
                    best=tot
    return int(best)
